async function init(){try{const r=indexedDB.open('home-nook',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');db=await request(r);state=await request(db.transaction('data').objectStore('data').get('state'))||initial();if(!valid(state))throw Error('数据格式异常，请恢复备份');const oldVersion=state.version;state=migrate(state);if(oldVersion!==state.version)await save();render();navigator.storage?.persist?.().catch(()=>{});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>notify('离线安装暂不可用，在线功能仍可使用'));}catch(e){$('#app').innerHTML=`<main class="shell"><h1>无法打开本地存储</h1><p>${esc(e.message)}。请使用普通浏览模式并允许网站存储后刷新。</p></main>`}}
async function save(){await new Promise((resolve,reject)=>{const t=db.transaction('data','readwrite');t.objectStore('data').put(state,'state');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)});}
async function mutate(fn,message){
 if(saving){notify('正在保存，请稍等');return false}
 const old=structuredClone(state);saving=true;
 try{fn();if(!valid(state))throw Error('输入格式不正确');await save();past.push(old);if(past.length>20)past.shift();future=[];render();if(message)notify(message);return true}
 catch(e){state=old;render();notify(e.message||'未能保存，请检查存储空间后重试');return false}
 finally{saving=false}
}
async function historyStep(redo=false){
 if(saving)return;const from=redo?future:past,to=redo?past:future;if(!from.length)return;
 const old=state;state=structuredClone(from.at(-1));saving=true;
 try{await save();from.pop();to.push(old);render();notify(redo?'已重做':'已撤销')}catch{state=old;notify('未能保存，请重试')}finally{saving=false}
}
