function sharedWalls(r){return ['left','right','top','bottom'].filter(side=>state.rooms.some(o=>o!==r&&(side==='left'||side==='right'?Math.abs((side==='left'?r.x:r.x+r.w)-(side==='left'?o.x+o.w:o.x))<.5&&r.y<o.y+o.h&&r.y+r.h>o.y:Math.abs((side==='top'?r.y:r.y+r.h)-(side==='top'?o.y+o.h:o.y))<.5&&r.x<o.x+o.w&&r.x+r.w>o.x))).map(x=>'shared-'+x).join(' ')}
const noteContent=n=>n.icon?noteIcon(n.icon):n.name?`<span class="note-name">${esc(n.name)}</span>`:'';
const noteStyle=n=>`left:${n.x}%;top:${n.y}%;width:${n.w}%;height:${n.h}%;--note:${n.color};--ink:${noteInk(n.color)};${n.openSide!=='none'?`border-${n.openSide}-color:transparent;`:''}`;
function dock(){return `<form class="map-dock" id="dockSearch"><input type="search" name="query" aria-label="搜索家里的物品" placeholder="搜索家里的物品…" value="${esc(q)}"><button class="dock-add" type="button" data-action="add" aria-label="添加">${icon('plus')}</button></form>`}
function bindDock(){if($('#dockSearch'))$('#dockSearch').onsubmit=e=>{e.preventDefault();q=e.target.elements.query.value.trim();group='';cabinet='';window.location.hash='items'}}
function render(){const route=window.location.hash,fixed=!['#items','#snack','#cart'].includes(route)&&!route.startsWith('#item/')&&!cellId();document.documentElement.classList.toggle('home-active',fixed);document.body.classList.toggle('home-active',fixed);if(route.startsWith('#item/')){renderItemDetails();return}if(detailId()){renderStorage();return}if(route==='#items'){renderItemsPage();return}if(route==='#snack'){renderSnackPage();return}if(route==='#cart'){renderCartPage();return}renderHome()}
function renderHome(){
 $('#app').innerHTML=`<main class="home-screen ${editing?'is-editing':''}"><header class="map-toolbar"><h1>我的家</h1><div class="map-tools">${ib('settings','更多功能','more')}${ib(editing?'check':'edit',editing?'完成编辑':'编辑平面图','toggleEdit')}</div></header><div class="map home-canvas" id="map">${state.rooms.map(r=>`<section class="room ${sharedWalls(r)}" data-room-box="${r.id}" style="left:${r.x}%;top:${r.y}%;width:${r.w}%;height:${r.h}%"><button class="room-label" data-room="${r.id}" aria-label="编辑房间 ${esc(r.name)}">${esc(r.name)}</button><div class="room-interior grid-surface" style="${gridStyle(activeGrid())}">${state.cabinets.filter(c=>c.room===r.id).map(c=>`<div class="cabinet note ${editing?'edit':''}" data-cabinet="${c.id}" style="${noteStyle(c)}"><button class="note-open" data-open-storage="${c.id}" aria-label="${esc(cabinetLocation(state,c))}">${noteContent(c)}</button>${editing?`<button class="cabinet-settings" data-edit-cabinet="${c.id}" aria-label="编辑收纳">${icon('edit')}</button>`:''}</div>`).join('')}</div>${editing?'<span class="resize room-resize"></span>':''}</section>`).join('')}</div>${editing?`${historyTools()}<div class="map-edit-actions"><button class="floating-pill" data-action="addRoom">${icon('plus')}房间</button><button class="floating-pill" data-action="addCabinet">${icon('plus')}收纳</button></div><p class="map-edit-hint">单指移动 · 双指缩放 · 自动对齐网格</p>`:''}${dock()}</main>`;bindDock();if(editing)bindDrag();
}
function pageHeader(title){return `<header class="storage-header">${ib('home','返回我的家','home')}<div><h1>${title}</h1></div></header>`}
function renderItemsPage(){
 $('#app').innerHTML=`<main class="shell items-page">${pageHeader('家里的物品')}<div class="list-top"><span class="muted">按名称、种类或位置查找</span><button class="primary" data-action="add">${icon('plus')} 收一件</button></div><div class="search">${icon('search')}<input id="search" type="search" placeholder="找什么？搜名称、种类或位置…" value="${esc(q)}" aria-label="搜索物品">${q?'<button data-action="resetSearch" aria-label="清除搜索">×</button>':''}</div><div class="filters"><button class="chip ${group?'':'active'}" data-group="">全部</button>${Object.keys(categories).map(g=>`<button class="chip ${g===group?'active':''}" data-group="${g}">${g}</button>`).join('')}</div><div id="results"></div></main>`;
 renderResults();$('#search').oninput=e=>{q=e.target.value;renderResults()};
}
function renderSnackPage(){
 if(pick)pick=snacks(state).find(i=>i.id===pick.id)||null;
 const available=snacks(state).length;
 $('#app').innerHTML=`<main class="shell snack-page">${pageHeader('想吃点什么')}<section class="snack-card panel">${pick?`${pick.photo?`<img class="snack-photo" src="${esc(pick.photo)}" alt="${esc(pick.name)}">`:`<div class="snack-placeholder">${icon('box')}</div>`}<h2>${esc(pick.name)}</h2><button class="location-link" data-open-storage="${pick.cabinet}">${icon('home')} ${esc(location(pick))}</button>`:`<div class="snack-placeholder">${icon('shuffle')}</div><h2>${available?'挑一件小零食':'还没有在收的零食'}</h2><p>${available?'让家里的零食给你一点灵感。':'收进一些零食后，就能在这里随机挑选。'}</p>`}<button class="primary full" data-action="random" ${available?'':'disabled'}>${icon('shuffle')} ${pick?'再来一个':'帮我挑一个'}</button>${available?'':'<button class="text-btn" data-action="add">＋ 收一件零食</button>'}</section></main>`;
}
function renderCartPage(){
 $('#app').innerHTML=`<main class="shell cart-page">${pageHeader('购物清单')}<section class="panel">${state.cart.length?state.cart.map(c=>`<div class="cart-row"><div><strong>${esc(c.name)}</strong><p>${esc(state.items.find(i=>i.id===c.id)?location(state.items.find(i=>i.id===c.id)):'手动添加')}</p></div><button class="icon" data-bought="${c.id}" title="已买到，补货 1" aria-label="已买到，补货 1">${icon('check')}</button><button class="icon" data-remove-cart="${c.id}" title="移出购物车" aria-label="移出购物车">${icon('close')}</button></div>`).join(''):'<p>补货清单是空的，缺什么就加进来。</p>'}<form id="cartForm" class="row" style="margin-top:20px"><input name="name" placeholder="手动记一件要买的…" required maxlength="100" aria-label="购物品名"><button type="submit" class="primary" aria-label="加入购物清单">${icon('plus')}</button></form></section></main>`;
 $('#cartForm').onsubmit=async e=>{e.preventDefault();const name=e.target.elements.namedItem('name').value.trim();if(!name)return;await mutate(()=>state.cart.push({id:uid(),name}))};
}
function detailId(){return window.location.hash.startsWith('#storage/')?window.location.hash.slice(9).split('/')[0]:''}
function cellId(){return window.location.hash.startsWith('#storage/')?window.location.hash.split('/')[2]||'':''}
function openStorage(id){$('#modal').close();elevationEdit=false;selectedCell='';detailQuery='';window.location.hash='storage/'+id}
function renderStorage(){
 if(placement){renderPlacement();return}
 const c=state.cabinets.find(x=>x.id===detailId());if(!c){window.location.hash='';return}if(cellId()){renderCellItems(c);return}
 if(!c.cells.some(x=>x.id===selectedCell))selectedCell=c.cells[0]?.id;const selected=c.cells.find(x=>x.id===selectedCell);
 $('#app').innerHTML=`<main class="home-screen elevation-screen ${elevationEdit?'elevation-edit':''}"><header class="map-toolbar">${ib('home','返回平面图','home')}<h1>${esc(elevationEdit?'编辑分格':c.name||'柜体立面')}</h1><div class="map-tools">${ib('settings','柜子设置','editStorage')}${ib(elevationEdit?'check':'edit',elevationEdit?'完成编辑':'编辑分格','toggleElevation')}</div></header><div class="elevation-canvas grid-surface" id="elevation" style="${gridStyle(activeGrid())}">${c.cells.map(n=>`<div class="cell note ${elevationEdit&&n.id===selectedCell?'selected':''}" data-cell="${n.id}" style="${noteStyle(n)}"><button class="note-open" data-open-cell="${n.id}" aria-label="${esc(n.name||'格子 '+(c.cells.indexOf(n)+1))}">${noteContent(n)}</button></div>`).join('')}${!c.cells.length?'<p class="canvas-empty">空柜子 · 点击编辑添加分格</p>':''}</div>${elevationEdit?`${historyTools()}<section class="cell-controls"><p class="gesture-hint">单指移动 · 双指缩放 · 网格吸附</p><div class="cell-control-row">${selected?`<button data-action="cellAppearance">${icon('edit')}外观</button><button data-action="copyCell">${icon('copy')}复制</button><button data-action="moveCell">${icon('move')}移动</button><button data-action="promoteCell">${icon('box')}转柜子</button>`:''}</div><div class="cell-control-row"><button data-action="addCell">${icon('plus')}分格</button>${selected?`<button data-action="cellSize">${icon('grid')}尺寸</button><button data-action="deleteCell" aria-label="删除空格子">${icon('trash')}</button>`:''}<button data-action="templates">布局模板</button></div></section>`:''}${dock()}</main>`;
 bindDock();bindCanvasZoom($('#elevation'));if(elevationEdit)bindCellDrag();
}
function renderCellItems(c){
 const cell=currentCell();if(!cell){window.location.hash='storage/'+c.id;return}
 const g=cell.groups.find(g=>g.id===groupId());if(groupId()&&!g){window.location.hash='storage/'+c.id+'/'+cell.id;return}
 $('#app').innerHTML=`<main class="shell storage-page"><header class="storage-header">${ib('home',g?'返回格子':'返回柜体立面',g?'backCell':'backElevation')}<div><h1>${esc(g?.name|| (g?'盒内分组':cell.name||'格子 '+(c.cells.indexOf(cell)+1)))}</h1><p>${esc(cabinetLocation(state,c))}</p></div>${ib('plus','添加物品','add')}</header><form class="search" id="cellSearchForm"><input type="search" id="detailSearch" placeholder="搜索物品、分组、Tag…" value="${esc(detailQuery)}" aria-label="搜索这个格子"></form><div class="tree-toolbar">${!g?'<button class="text-btn" data-action="addGroup">＋ Group</button>':''}<span></span><button class="icon" data-action="undo" aria-label="撤销" ${past.length?'':'disabled'}>${icon('undo')}</button><button class="icon" data-action="redo" aria-label="重做" ${future.length?'':'disabled'}>${icon('redo')}</button></div><div id="storageItems"></div></main>`;
 renderStorageItems();$('#detailSearch').oninput=e=>{detailQuery=e.target.value;renderStorageItems()};$('#cellSearchForm').onsubmit=e=>e.preventDefault();
}
function renderStorageItems(){
 const cell=currentCell(),items=search(state,detailQuery,'',detailId()).filter(i=>i.cell===cellId()&&(!groupId()||i.groupId===groupId()));
 const list=arr=>arr.length?arr.map(itemCard).join(''):'<p class="tree-empty">这里还没有物品</p>';
 if(groupId()){$('#storageItems').innerHTML=`<div class="section-label">物品 · ${items.length}</div><div class="items">${list(items)}</div>`;bindItemSwipes();return}
 const direct=items.filter(i=>!i.groupId),groups=cell.groups.filter(g=>!detailQuery||g.name.toLowerCase().includes(detailQuery.toLowerCase())||items.some(i=>i.groupId===g.id));
 $('#storageItems').innerHTML=`<div class="section-label">物品 · ${items.length} <span class="muted">Group 可展开收起</span></div><div class="storage-tree">${direct.length||!cell.groups.length?`<section class="tree-direct"><h2>未分组 <span>${direct.length}</span></h2><div class="items">${list(direct)}</div></section>`:''}${groups.map((g,k)=>{const contents=items.filter(i=>i.groupId===g.id),name=g.name||'分组 '+(k+1);return `<details class="tree-group" data-tree-group="${g.id}" ${detailQuery||!closedGroups.has(g.id)?'open':''}><summary><span>${esc(name)}</span><small>${contents.length}</small><button class="group-menu-button" data-group-menu="${g.id}" aria-label="${esc(name)}的操作">•••</button></summary><div class="tree-branch"><div class="items">${list(contents)}</div></div></details>`}).join('')}${!groups.length&&!direct.length&&detailQuery?'<p class="tree-empty">没有匹配的物品或分组</p>':''}</div>`;
 bindItemSwipes();document.querySelectorAll('[data-tree-group]').forEach(el=>el.ontoggle=()=>{if(el.open)closedGroups.delete(el.dataset.treeGroup);else closedGroups.add(el.dataset.treeGroup)});
}

function moreMenu(){dialog('更多',`<div class="menu-list"><button data-action="items">${icon('box')}全部物品</button><button data-action="snack">${icon('shuffle')}想吃点什么</button><button data-action="cart">${icon('cart')}购物清单 <small>${state.cart.length}</small></button><button data-action="grid">${icon('grid')}网格设置</button><button data-action="settings">${icon('download')}备份与设置</button></div>`)}
function appearanceFields(n){return `<details open><summary>颜色</summary><div class="swatches">${palette.map(color=>`<button type="button" class="swatch" style="background:${color}" data-form-color="${color}" aria-label="颜色 ${color}"></button>`).join('')}<input type="color" name="color" value="${n?.color||palette[0]}" aria-label="自定义颜色"></div></details><label>名称（可选）<input name="name" maxlength="80" value="${esc(n?.name||'')}" placeholder="例如：杂物"></label><label>显示方式<select name="display"><option value="icon" ${n?.icon?'selected':''}>图标</option><option value="name" ${n?.name&&!n?.icon?'selected':''}>名称</option><option value="none" ${!n?.icon&&!n?.name?'selected':''}>留白</option></select></label><fieldset class="icon-picker"><legend>分类图标</legend>${Object.entries(categoryIcons).map(([key,v])=>`<label title="${v.label}"><input type="radio" name="icon" value="${key}" ${n?.icon===key?'checked':''}>${noteIcon(key)}<span>${v.label}</span></label>`).join('')}</fieldset><fieldset class="edge-options"><legend>开放边</legend>${openSides.map((side,i)=>`<label><input type="radio" name="openSide" value="${side}" ${(n?.openSide||'none')===side?'checked':''}><span>${['封闭','上','右','下','左'][i]}</span></label>`).join('')}</fieldset>`}
document.addEventListener('change',e=>{if(e.target.closest('.icon-picker'))$('#modal select[name="display"]').value='icon';if(e.target.matches('#modal input[name="name"]')&&$('#modal select[name="display"]')?.value==='none'&&e.target.value.trim())$('#modal select[name="display"]').value='name'});
function appearanceData(d){return {color:d.color,name:d.display==='none'?'':d.name.trim(),icon:d.display==='icon'?d.icon||'archive':'',openSide:d.openSide}}
function editCellAppearance(){const c=state.cabinets.find(x=>x.id===detailId()),n=c.cells.find(x=>x.id===selectedCell);dialog('格子外观',`<form id="appearanceForm">${appearanceFields(n)}<button class="primary full">保存</button></form>`);$('#appearanceForm').onsubmit=async e=>{e.preventDefault();if(await mutate(()=>Object.assign(currentCabinet().cells.find(x=>x.id===selectedCell),appearanceData(Object.fromEntries(new FormData(e.target)))),'格子已保存'))$('#modal').close()}}
async function setCellColor(color){const c=state.cabinets.find(x=>x.id===detailId());await mutate(()=>c.cells.find(x=>x.id===selectedCell).color=color)}
window.addEventListener('hashchange',()=>{detailQuery='';canvasZoom=1;openSwipe='';render();window.scrollTo({top:0,behavior:'instant'})});
function renderResults(){let a=search(state,q,group,cabinet);$('#results').innerHTML=`<div class="section-label"><span>${cabinet?esc(cabinetLocation(state,state.cabinets.find(c=>c.id===cabinet))):'家里的物品'} <span class="muted">${a.length}</span></span>${cabinet?'<button class="text-btn" data-action="allCabinets">查看全部 ×</button>':'<span class="muted">点击查看详情 · 左滑操作</span>'}</div><div class="items">${a.length?a.map(itemCard).join(''):`<div class="empty">${q?'没有找到，换个关键词试试。':'这里还空着，把第一件物品收进来吧。'}<br><button class="text-btn" data-action="add">＋ 收一件</button></div>`}</div>`;bindItemSwipes()}
function dialog(title,html){$('#modal').classList.remove('item-dialog');$('#modal').innerHTML=`<div class="dialog-head"><h2>${title}</h2>${ib('close','关闭','close')}</div>${html}`;if(!$('#modal').open)$('#modal').showModal()}
async function compress(file){if(!file.type.startsWith('image/'))throw Error('请选择图片');if(file.size>30*1024*1024)throw Error('图片不能超过 30MB');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=()=>reject(Error('无法读取图片，请换成 JPG、PNG 或 WebP'));im.src=url});const ratio=Math.min(1,480/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*ratio));c.height=Math.max(1,Math.round(img.height*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);let data=c.toDataURL('image/webp',.25);if(!data.startsWith('data:image/webp'))data=c.toDataURL('image/jpeg',.25);return data}finally{URL.revokeObjectURL(url)}}
function editItem(id,targetGroup=''){if(!state.cabinets.length){notify('先添加一个柜子');editCabinet();return}if(!state.cabinets.some(c=>c.cells.length)){notify('先在柜体编辑中添加分格');openStorage(state.cabinets[0].id);elevationEdit=true;render();return}const i=state.items.find(x=>x.id===id);let photo=i?.photo||'',busy=false;const g=i?.group||'零食';dialog(i?'编辑物品':'收一件物品',`<form id="itemForm"><label class="upload">${photo?`<img src="${esc(photo)}" alt="物品照片">`:icon('camera')}<span>添加照片 · 自动压缩到轻量画质</span><input type="file" accept="image/*" id="photo"></label><label>物品名<input name="name" required maxlength="100" value="${esc(i?.name||'')}" placeholder="例如：海盐苏打饼干"></label><div class="row"><label>大种类<select id="group" name="group">${Object.keys(categories).map(k=>`<option ${k===g?'selected':''}>${k}</option>`).join('')}</select></label><label>小种类<select id="category" name="category"></select></label></div><label>位置<select name="cabinet">${state.cabinets.filter(c=>c.cells.length).map(c=>`<option value="${c.id}" ${c.id===(i?.cabinet||detailId()||cabinet)?'selected':''}>${esc(cabinetLocation(state,c))}</option>`).join('')}</select></label><label>格子<select name="cell" id="itemCell"></select></label><label>盒内分组（可选）<select name="groupId" id="itemGroup"></select></label><div class="row"><label>数量<input name="qty" type="number" min="0" max="9999" step="1" required value="${i?.qty??1}"></label><label>单位<input name="unit" maxlength="12" value="${esc(i?.unit||'件')}" placeholder="件 / 包 / 个"></label></div><div class="row"><label>Tag（可选，逗号分隔）<input name="tags" maxlength="310" value="${esc(i?.tags?.join(', ')||'')}" placeholder="露营, 备用"></label><label>到期日（可选）<input name="expiry" type="date" value="${esc(i?.expiry||'')}"></label></div><label>备注<textarea name="note" maxlength="1000" rows="2" placeholder="第几层、规格…">${esc(i?.note||'')}</textarea></label><button class="primary full" type="submit">${icon('check')} 保存</button>${i?'<button type="button" class="danger" id="deleteItem">删除物品</button>':''}</form>`);paginateItemForm();const subgroupOptions=()=>{const c=state.cabinets.find(c=>c.id===$('#itemForm select[name="cabinet"]').value),n=c.cells.find(n=>n.id===$('#itemCell').value);$('#itemGroup').innerHTML='<option value="">不分组</option>'+(n?.groups||[]).map((g,k)=>`<option value="${g.id}" ${g.id===(i?.groupId||targetGroup||groupId())?'selected':''}>${esc(g.name||'分组 '+(k+1))}</option>`).join('')};const cellOptions=()=>{const c=state.cabinets.find(c=>c.id===$('#itemForm select[name="cabinet"]').value);$('#itemCell').innerHTML=c.cells.map((n,k)=>`<option value="${n.id}" ${n.id===(i?.cell||cellId())?'selected':''}>${esc(n.name||'格子 '+(k+1))}</option>`).join('');subgroupOptions()};cellOptions();$('#itemCell').onchange=subgroupOptions;$('#itemForm select[name="cabinet"]').onchange=cellOptions;const options=()=>$('#category').innerHTML=categories[$('#group').value].map(c=>`<option ${c===i?.category?'selected':''}>${c}</option>`).join('');options();$('#group').onchange=options;$('#photo').onchange=async e=>{const f=e.target.files[0];if(!f)return;busy=true;try{photo=await compress(f);let img=$('.upload img');if(!img){img=document.createElement('img');$('.upload').prepend(img)}img.src=photo;notify(`照片已压缩至约 ${Math.ceil(photo.length*.75/1024)} KB`)}catch(e){notify(e.message)}finally{busy=false}};$('#itemForm').onsubmit=async e=>{e.preventDefault();if(busy){notify('照片正在压缩，请稍等');return}if(Number($('#itemForm').dataset.page)<2){$('#itemForm').advance();return}const d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();if(!d.name){notify('请填写物品名');return}const data={...d,id:i?.id||uid(),qty:Number(d.qty),unit:d.unit.trim()||'件',tags:[...new Set(d.tags.split(/[,，]/).map(t=>t.trim()).filter(Boolean))],photo};if(await mutate(()=>{if(i)state.items[state.items.findIndex(x=>x.id===i.id)]=data;else state.items.push(data)},'已收好'))$('#modal').close()};if(i)$('#deleteItem').onclick=()=>{dialog('删除这件物品？',`<p>照片和物品记录将移除，购物清单不受影响。</p><button class="danger full" id="confirmDelete">确认删除</button>`);$('#confirmDelete').onclick=async()=>{await mutate(()=>{state.items=state.items.filter(x=>x.id!==i.id)},'已删除');$('#modal').close()}}}
