function dragRect(el,c,parent,others,{room=false,grid=activeGrid(),preview=false}={}){
 const keyTarget=room?el:el.querySelector('.note-open');
 const resolve=(candidate,nearest=false)=>fitRect(candidate,others,grid,{nearest});
 if(keyTarget){keyTarget.title='方向键移动，Shift + 方向键缩放';keyTarget.onkeydown=async e=>{
  if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();
  const d={...c},dx=(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0)*100/grid.cols,dy=(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0)*100/grid.rows;
  if(e.shiftKey){d.w+=dx;d.h+=dy}else{d.x+=dx;d.y+=dy}const next=resolve(d);
  if(next){if(preview){Object.assign(c,next);paint()}else await mutate(()=>Object.assign(c,next))}
 }}
 const points=new Map();let old,bounds,start,base,distance=0,moved=false,historyBefore,roomResize=false;
 const paint=()=>{const box=room?el.closest('.room'):el;Object.assign(box.style,{left:c.x+'%',top:c.y+'%',width:c.w+'%',height:c.h+'%'})};
 const resetBase=()=>{base={...c};const a=[...points.values()];start=a[0];distance=a.length>1?Math.hypot(a[1].x-a[0].x,a[1].y-a[0].y):0};
 el.onpointerdown=e=>{
  if(e.button!==0||saving||e.target.closest('.cabinet-settings'))return;e.stopPropagation();e.preventDefault();
  if(!points.size){if(el.dataset.cell){selectedCell=c.id;parent.querySelectorAll('.selected').forEach(n=>n.classList.remove('selected'));el.classList.add('selected')}old={...c};historyBefore=structuredClone(state);bounds=parent.getBoundingClientRect();moved=false}
  roomResize=!!e.target.closest('.room-resize');points.set(e.pointerId,{x:e.clientX,y:e.clientY});el.setPointerCapture(e.pointerId);resetBase();
 };
 el.onpointermove=e=>{
  if(!points.has(e.pointerId))return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});const a=[...points.values()];
  const dx=(a[0].x-start.x)/bounds.width*100,dy=(a[0].y-start.y)/bounds.height*100;
  if(a.length===1&&Math.abs(dx)+Math.abs(dy)<.8&&!moved)return;
  if(a.length>1&&distance<1){resetBase();return}const candidate=a.length>1?pinchRect(base,distance,Math.hypot(a[1].x-a[0].x,a[1].y-a[0].y),grid):roomResize?{...base,w:base.w+dx,h:base.h+dy}:{...base,x:base.x+dx,y:base.y+dy};
  const next=resolve(candidate);moved=true;dragBlocked=true;if(next){Object.assign(c,next);paint();el.classList.remove('blocked')}else el.classList.add('blocked');
 };
 const finish=async(e,cancel=false)=>{
  if(!points.has(e.pointerId))return;points.delete(e.pointerId);if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);
  if(points.size&&!cancel){resetBase();return}points.clear();el.classList.remove('blocked');
  if(cancel)Object.assign(c,old);
  if(moved&&!cancel&&!preview){saving=true;try{if(!valid(state))throw Error();await save();past.push(historyBefore);if(past.length>20)past.shift();future=[]}catch{Object.assign(c,old);notify('位置未保存，已恢复')}finally{saving=false}}
  if(preview)paint();else if(moved||cancel)render();setTimeout(()=>dragBlocked=false,200);
 };
 el.onpointerup=e=>finish(e);el.onpointercancel=e=>finish(e,true);el.onlostpointercapture=e=>{if(points.has(e.pointerId))finish(e,true)};
}
function bindDrag(){document.querySelectorAll('.cabinet').forEach(el=>{const c=state.cabinets.find(x=>x.id===el.dataset.cabinet);dragRect(el,c,el.closest('.room-interior'),state.cabinets.filter(x=>x.room===c.room&&x!==c))});document.querySelectorAll('.room-label,.room-resize').forEach(el=>{const r=state.rooms.find(x=>x.id===el.closest('.room').dataset.roomBox);dragRect(el,r,$('#map'),state.rooms.filter(x=>x!==r),{room:true})})}
