function paginateItemForm(){
 const form=$('#itemForm'),children=[...form.children],submit=form.querySelector('button[type="submit"]'),remove=form.querySelector('#deleteItem');
 const pages=[children.slice(0,3),children.slice(3,7),children.slice(7,9)];if(remove)pages[2].push(remove);
 form.classList.add('item-wizard');form.closest('dialog').classList.add('item-dialog');
 const sections=pages.map(nodes=>{const page=document.createElement('section');page.className='form-page';nodes.forEach(n=>page.append(n));form.append(page);return page});
 const footer=document.createElement('div');footer.className='wizard-footer';footer.innerHTML='<div class="wizard-nav"><button type="button" id="prevPage" aria-label="上一页">◀</button><span id="pageCount"></span><button type="button" id="nextPage" aria-label="下一页">▶</button></div>';
 footer.append(submit);form.append(footer);
 const show=p=>{form.dataset.page=p;sections.forEach((n,i)=>n.hidden=i!==p);$('#prevPage').disabled=p===0;$('#nextPage').disabled=p===2;$('#pageCount').textContent=['1 / 3 · 物品','2 / 3 · 放在哪里','3 / 3 · 补充信息'][p];submit.hidden=p!==2;form.closest('dialog').scrollTop=0};
 form.advance=()=>{const page=Number(form.dataset.page);for(const input of sections[page].querySelectorAll('input,select'))if(!input.reportValidity())return;show(Math.min(2,page+1))};
 $('#prevPage').onclick=()=>show(Math.max(0,Number(form.dataset.page)-1));$('#nextPage').onclick=form.advance;show(0);
}

